//! Optical kerning (`AutoKernType.OPTICAL`).
//!
//! The reference is `out/opt_kern.pdf`: Photoshop set a layer with optical
//! kerning and wrote the pen position of every glyph into the PDF, so the
//! expected adjustment per pair is `advance_ps - face_advance`. The fixture is
//! regenerated by `tools/gen_corpus.py`-style jobs (`autokern: "optical"`).

use std::path::PathBuf;

use photocraft_text::font::Face;
use photocraft_text::optical::optical_kern;

fn font_path(name: &str) -> PathBuf {
    let home = std::env::var("HOME").expect("HOME");
    [&home, ".local/share/photocraft/wine/drive_c/windows/Fonts", name].iter().collect()
}

fn face_bytes() -> Vec<u8> {
    std::fs::read(font_path("NotoSans-Regular.ttf")).expect("Noto Sans")
}

/// Photoshop's per-pair kerning for `AVATAR To Ty. WAVE`, in 1/1000 em,
/// measured from the PDF export at 48 pt.
const PHOTOSHOP: [(&str, &str, f32); 10] = [
    ("A", "V", -54.3),
    ("V", "A", -53.8),
    ("A", "T", -73.0),
    ("T", "A", -72.5),
    ("A", "R", -1.0),
    ("T", "o", -91.3),
    ("T", "y", -76.1),
    ("y", ".", -64.3),
    ("W", "A", -39.5),
    ("V", "E", -2.5),
];

#[test]
fn optical_kern_tightens_the_pairs_photoshop_tightens() {
    let bytes = face_bytes();
    let face = Face::parse(&bytes).expect("parse");
    let size = 48.0;
    let upm = face.units_per_em() as f32;
    for (a, b, expected) in PHOTOSHOP {
        let (ga, gb) = (face.glyph_index(a.chars().next().unwrap()), face.glyph_index(b.chars().next().unwrap()));
        let (ga, gb) = (ga.expect("glyph a"), gb.expect("glyph b"));
        let units = optical_kern(&face, ga, gb, size) / size * 1000.0;
        let _ = upm;
        assert!(units < 0.0, "{a}{b}: optical kerning must tighten, got {units}");
        assert!(
            (units - expected).abs() < 30.0,
            "{a}{b}: {units:.1}/1000 em, Photoshop {expected}"
        );
    }
}

#[test]
fn optical_kern_leaves_pairs_without_facing_outlines_alone() {
    let bytes = face_bytes();
    let face = Face::parse(&bytes).expect("parse");
    let space = face.glyph_index(' ').expect("space");
    let a = face.glyph_index('A').expect("A");
    assert_eq!(optical_kern(&face, space, a, 48.0), 0.0);
    assert_eq!(optical_kern(&face, a, space, 48.0), 0.0);
    // `A` and `R` overlap vertically; a pair that does not (period over a
    // comma has no shared rows) must not be kerned.
    // A glyph with no outline has nothing to measure.  Noto gives a soft
    // hyphen a real outline, so look for a candidate whose bbox is empty.
    let empty = ['\u{200B}', '\u{FEFF}', '\u{00AD}']
        .into_iter()
        .filter_map(|c| face.glyph_index(c))
        .find(|&gid| face.glyph_bbox(gid).is_none());
    if let Some(empty) = empty {
        assert_eq!(optical_kern(&face, empty, a, 48.0), 0.0);
        assert_eq!(optical_kern(&face, a, empty, 48.0), 0.0);
    }
}

#[test]
fn optical_kern_scales_with_point_size() {
    let bytes = face_bytes();
    let face = Face::parse(&bytes).expect("parse");
    let (a, v) = (face.glyph_index('A').unwrap(), face.glyph_index('V').unwrap());
    let small = optical_kern(&face, a, v, 24.0);
    let large = optical_kern(&face, a, v, 96.0);
    assert!((large / small - 4.0).abs() < 1e-3, "kerning must scale linearly: {small} {large}");
}
